// AIR-73: la view v_data_source_freshness ya calcula `stale` por fuente con su umbral.
// Agregamos conteos + un array estructurado stale_rows para render HTML.
const rows = $input.all().map(i => i.json);
const staleRows = rows.filter(r => r.stale === true);
const resumen = rows
  .map(r => r.fuente + '=' + (r.dias_desde_ultimo == null ? 'vacia' : r.dias_desde_ultimo + 'd'))
  .join(', ');
const detalleStale = staleRows
  .map(r => '• ' + r.fuente + ' (' + r.cadencia + '): ' + (r.dias_desde_ultimo == null ? 'tabla vacia' : r.dias_desde_ultimo + ' dias sin datos, umbral ' + r.umbral_dias + 'd') + ', ultima ' + (r.ultima_fecha || '—'))
  .join('\n');
return [{ json: {
  total_fuentes: rows.length,
  stale_count: staleRows.length,
  resumen,
  detalle_stale: detalleStale,
  stale_rows: staleRows.map(r => ({
    fuente: r.fuente, cadencia: r.cadencia,
    dias_desde_ultimo: r.dias_desde_ultimo, umbral_dias: r.umbral_dias,
    ultima_fecha: r.ultima_fecha
  }))
} }];

// AIR-73: render HTML del correo de alerta de frescura (sin LLM, datos controlados).
const d = $json;
const rows = Array.isArray(d.stale_rows) ? d.stale_rows : [];
const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const trs = rows.map(r => {
  const atraso = r.dias_desde_ultimo == null ? 'tabla vacía' : (r.dias_desde_ultimo + ' días');
  return '<tr>' +
    '<td style="padding:10px 12px;border-bottom:1px solid #eee;font-weight:600;">' + esc(r.fuente) + '</td>' +
    '<td style="padding:10px 12px;border-bottom:1px solid #eee;color:#555;">' + esc(r.cadencia) + '</td>' +
    '<td style="padding:10px 12px;border-bottom:1px solid #eee;color:#c0392b;font-weight:700;">' + esc(atraso) + '</td>' +
    '<td style="padding:10px 12px;border-bottom:1px solid #eee;color:#999;">umbral ' + esc(r.umbral_dias) + 'd</td>' +
    '<td style="padding:10px 12px;border-bottom:1px solid #eee;color:#999;">' + esc(r.ultima_fecha || '—') + '</td>' +
  '</tr>';
}).join('');
const html =
'<div style="margin:0;background:#f4f4f5;padding:24px 0;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1a1a1a;">' +
  '<div style="max-width:640px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;border:1px solid #e5e5e5;">' +
    '<div style="background:#c0392b;color:#fff;padding:18px 24px;">' +
      '<div style="font-size:18px;font-weight:700;">⚠️ Corte de datos detectado</div>' +
      '<div style="font-size:13px;opacity:.9;margin-top:2px;">Aire de Agua · Sensor de frescura (E_Data_Freshness_Check)</div>' +
    '</div>' +
    '<div style="padding:22px 24px;">' +
      '<p style="margin:0 0 16px;font-size:15px;"><b style="color:#c0392b;">' + esc(d.stale_count) + '</b> de <b>' + esc(d.total_fuentes) + '</b> fuentes sin datos frescos:</p>' +
      '<table style="width:100%;border-collapse:collapse;font-size:13px;">' +
        '<thead><tr style="text-align:left;color:#888;font-size:11px;text-transform:uppercase;letter-spacing:.04em;border-bottom:2px solid #eee;">' +
          '<th style="padding:8px 12px;">Fuente</th><th style="padding:8px 12px;">Cadencia</th>' +
          '<th style="padding:8px 12px;">Atraso</th><th style="padding:8px 12px;">Umbral</th><th style="padding:8px 12px;">Última</th>' +
        '</tr></thead><tbody>' + trs + '</tbody>' +
      '</table>' +
      '<p style="margin:18px 0 0;font-size:12px;color:#999;border-top:1px solid #eee;padding-top:14px;line-height:1.6;">Todas las fuentes: ' + esc(d.resumen) + '</p>' +
    '</div>' +
  '</div>' +
  '<p style="text-align:center;color:#bbb;font-size:11px;margin:14px 0 0;">Generado automáticamente por n8n · revisar ingesta de la(s) fuente(s) listada(s)</p>' +
'</div>';
return [{ json: { html, text: d.detalle_stale, stale_count: d.stale_count, total_fuentes: d.total_fuentes, resumen: d.resumen } }];
